test:
assert cd("/tmp", "~/proj", home="/home/me") == "/home/me/proj"
assert (
    cd("/tmp", "~alice/docs", home_map={"alice": "/Users/alice"}) == "/Users/alice/docs"
)
try:
    cd("/tmp", "~bob/docs", home_map={"alice": "/Users/alice"})
except (ValueError, AssertionError):
    pass
else:
    assert False, "expected input validation error"

assert cd("/", "a/c", links={"/a": "/b/..", "/c": "/d"}) == "/d"
try:
    cd("/a", "b", links={"/a/b": "/x", "/x": "/a/b"})
except (ValueError, AssertionError):
    pass
else:
    assert False, "expected input validation error"
